// The desktop app as Kiln's host: Go runs natively in the app
// (desktop/), and the page reaches it through the Kiln service's
// bindings (bindings/, generated by wails3). Files save through the OS's
// Save dialog, links open in the system browser, and the app dials
// worlds itself, so it can add them. This file takes the bindings as an
// argument rather than importing them, so tests fake them.
import type { Host, Ranges } from "./host.ts";
import { toBase64 } from "./host.ts";
import type { Event, Store } from "./store.ts";
import * as str from "./str.gen.ts";

// batchEvent is the Wails event each of Go's batches comes as, its data
// the batch's JSON (desktop/kiln.go).
export const batchEvent = "kiln:batch"; // str:ok: an event name

// Kiln is what the page calls of desktop/kiln.go's Kiln service: its
// generated bindings (bindings/github.com/latrani/Kiln/desktop).
export interface Kiln {
  Act(action: string): Promise<void>;
  Check(field: string, value: string): Promise<string>;
  Over(text: string, maxLineBytes: number, newlineMode: string): Promise<number[][]>;
  SaveAs(name: string, data: string): Promise<void>;
  OpenURL(link: string): Promise<void>;
  Start(): Promise<void>;
}

// desktopHost is the desktop app's host. Notifications don't show yet:
// the app has no notifications service.
export function desktopHost(kiln: Kiln): Host {
  return {
    check: (field, value) => kiln.Check(field, value),
    over: async (text, maxLineBytes, newlineMode) => (await kiln.Over(text, maxLineBytes, newlineMode)) as Ranges,
    // SaveAs takes the bytes as base64, as Wails passes a []byte.
    saveFile: (name, bytes) => { kiln.SaveAs(name, toBase64(bytes)).catch((e) => console.error("save", e)); },
    notify: () => {},
    permission: async () => "unsupported",
    askPermission: async () => "unsupported",
    whyNoNotify: (p) => (p === "denied" ? str.desktopNotifyDenied() : p === "unsupported" ? str.desktopNotifyUnsupported() : ""),
    worlds: true,
  };
}

// openLinks sends a click on a link that would open a new window to the
// system browser instead (the webview would open it in itself, or not at
// all). It listens in the capture phase, so it sees the click first.
export function openLinks(doc: EventTarget, open: (url: string) => Promise<void>): void {
  doc.addEventListener("click", (e) => {
    const a = (e.target as Element | null)?.closest?.("a[target=_blank]") as HTMLAnchorElement | null;
    if (!a) return;
    e.preventDefault();
    open(a.href).catch((err) => console.error("open", err));
  }, { capture: true });
}

// run runs the page over the Kiln service as boot runs it over the
// wasm: each kiln:batch into the store, and what was done before the
// first batch sent after it, in order (typing.ts). on listens to a
// Wails event; it's set before Go starts, so no batch comes before it.
export async function run(store: Store, kiln: Kiln, on: (name: string, f: (data: string) => void) => void): Promise<void> {
  const typing = store.state.typing!;
  store.set({ act: (o: object) => typing.act(o) });
  let running = false;
  on(batchEvent, (json) => {
    try {
      const batch: Event[] = JSON.parse(json);
      store.apply(batch);
    } catch (e) {
      console.error(e);
    }
    if (!running) {
      running = true;
      const s = store.state;
      typing.ready((o) => { kiln.Act(JSON.stringify(o)).catch((e) => console.error("act", e)); }, s.chars[s.active] ? s.active : "");
      store.set({}); // draw the typing where it went
    }
  });
  store.set({ phase: "running", progress: undefined });
  try {
    await kiln.Start();
  } catch (e) {
    console.error(e);
    store.set({ phase: "stopped" });
  }
}
